// Calculate surface area of bounding box
auto surface_area = [](const real3<T>& bmin, const real3<T>& bmax) {
    real3<T> size = bmax - bmin;
    return 2.0 * (size.x * size.y + size.y * size.z + size.z * size.x);
};

// Calculate cost for a split
auto calculate_cost = [&](int axis, T cut_pos, int left_count, int right_count) {
    real3<T> left_bmin = bmin, left_bmax = bmax;
    real3<T> right_bmin = bmin, right_bmax = bmax;

    // Update left and right bounding boxes
    if (axis == 0) {
        left_bmax.x = cut_pos;
        right_bmin.x = cut_pos;
    } else if (axis == 1) {
        left_bmax.y = cut_pos;
        right_bmin.y = cut_pos;
    } else {
        left_bmax.z = cut_pos;
        right_bmin.z = cut_pos;
    }

    // Calculate surface areas
    T left_sa = surface_area(left_bmin, left_bmax);
    T right_sa = surface_area(right_bmin, right_bmax);

    // Calculate cost
    T left_cost = left_sa * left_count;
    T right_cost = right_sa * right_count;
    return left_cost + right_cost;
};

// Find the best split for each axis
T min_cost = std::numeric_limits<T>::max();
int best_axis = 0;
T best_cut_pos = 0.0;

for (int axis = 0; axis < 3; axis++) {
    // Calculate bin sizes
    T bin_size = (bmax[axis] - bmin[axis]) / static_cast<T>(bins->num_bins);

    // Try all possible cut positions between bins
    for (int bin = 0; bin < bins->num_bins - 1; bin++) {
        T cut_pos = bmin[axis] + (bin + 0.5) * bin_size;

        // Count primitives on each side
        int left_count = 0;
        int right_count = bins->total_prims;

        for (int b = 0; b < bins->num_bins; b++) {
            if (b <= bin) {
                left_count += bins->bin_counts[b];
            } else {
                right_count -= bins->bin_counts[b];
            }
        }

        // Calculate cost
        T cost = calculate_cost(axis, cut_pos, left_count, right_count);

        // Update best split if this is better
        if (cost < min_cost) {
            min_cost = cost;
            best_axis = axis;
            best_cut_pos = cut_pos;
        }
    }
}

// Set output parameters
cut_pos[best_axis] = best_cut_pos;
*minCostAxis = best_axis;

return true;

